package com.ne.business.dflq.can.controller;

import com.ne.boot.common.entity.Page;
import com.ne.boot.common.entity.Response;
import com.ne.business.dflq.can.entity.CanRecordFile;
import com.ne.business.dflq.can.entity.CanRecordTask;
import com.ne.business.dflq.can.entity.dto.AddFileDTO;
import com.ne.business.dflq.can.entity.query.CanRecordFileQuery;
import com.ne.business.dflq.can.entity.vo.CanRecordFileVo;
import com.ne.business.dflq.can.service.CanRecordFileService;
import com.ne.business.dflq.can.service.CanRecordTaskService;
import com.ne.business.dflq.can.service.ExcelExportService;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.BeanUtils;
import org.springframework.util.CollectionUtils;
import org.springframework.web.bind.annotation.*;

import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * CAN数据任务详情控制器
 *
  @author weihong
  @date 2026-3-02
 */
@Api(tags = "事后录制任务详情相关")
@RestController
@Slf4j
@RequestMapping("/canRecordFile")
@RequiredArgsConstructor
public class CanRecordFileController {

    private final CanRecordFileService canRecordFileService;

    private final CanRecordTaskService canRecordTaskService;

    private final ExcelExportService exportService;

    @ApiOperation("查询")
    @GetMapping("/list")
    public Response list(CanRecordFileQuery query, Page page) {
        List<CanRecordFileVo> fileList = canRecordFileService.query(query, page);
        int count = canRecordFileService.getCount(query);
        page.setPageIndex(page.getPageIndex());
        page.setPageSize(page.getPageSize());
        page.setTotalCount((long) count);
//        List<CanRecordFileVo> voList = convertToVoList(fileList);
        return Response.success(fileList, page);
    }

    @ApiOperation("文件下载")
    @PostMapping("/download")
    public void download(@RequestBody CanRecordFileQuery query, HttpServletResponse response) {
        try {
            // 查询数据
            List<CanRecordFile> fileList = canRecordFileService.selectData(query);
            if (CollectionUtils.isEmpty(fileList)) {
                throw new RuntimeException("没有可下载的文件");
            }
            List<CanRecordFileVo> voList = convertToVoList(fileList);

            // 根据第一个文件的taskId查询任务名称作为文件名
            String taskName;
            Long taskId = fileList.get(0).getTaskId();
            if (taskId != null) {
                CanRecordTask task = canRecordTaskService.getById(taskId);
                if (task != null && task.getTaskName() != null) {
                    taskName = task.getTaskName();
                } else {
                    taskName = "录制文件";
                }
                voList.forEach(vo -> vo.setTaskName(taskName));
            } else {
                taskName = "录制文件";
            }

            // 打印voList
            voList.forEach(vo -> log.info("voList: {}", vo));

            // 生成Excel + ASC文件压缩包
            exportService.exportExcelWithAscFiles(voList, taskName, response);
        } catch (Exception e) {
            log.error("文件下载失败", e);
            throw new RuntimeException("文件下载失败: " + e.getMessage(), e);
        }
    }

    /**
     * 实体列表转VO列表
     * @param fileList 实体列表
     * @return VO列表
     */
    private List<CanRecordFileVo> convertToVoList(List<CanRecordFile> fileList) {
        if (fileList == null || fileList.isEmpty()) {
            return new ArrayList<>();
        }
        List<CanRecordFileVo> voList = new ArrayList<>();
        for (CanRecordFile file : fileList) {
            CanRecordFileVo vo = new CanRecordFileVo();
            BeanUtils.copyProperties(file, vo);
            voList.add(vo);
        }
        return voList;
    }

    @ApiOperation("任务转换")
    @PostMapping("/convert")
    public Response convert(@RequestBody CanRecordFileQuery query) {
        //更新状态
        canRecordFileService.recordFileConvert(query);
        return Response.success();
    }

    @ApiOperation("新增记录")
    @PostMapping("/add")
    public Response add(@RequestBody AddFileDTO dto) {
        canRecordFileService.add(dto);
        return Response.success();
    }

}

